    if(solHave!=null&&BigInt(solHave)<feeL+10000n)throw Error(`This account has ${solStr(solHave)} SOL. Bridging needs about ${solStr(feeL+10000n)} SOL for ${feeL>0n?'the bridge fee and ':''}the Solana network fee. Add SOL to ${a.sol} and try again.`);
    await approveReview({head:`Bridge ${amount(prep.review.gross)} ${r.symbol} to Monero`,rows:[['You send',amount(prep.review.gross)+' '+r.symbol],['Token fee',amount(prep.review.fee)+' '+r.symbol],['You receive',amount(prep.review.net)+' open '+r.symbol],...(feeL>0n?[['Bridge fee',solStr(feeL)+' SOL']]:[]),['Solana network fee','about 0.000005 SOL'],['Paid from','This account’s SOL'+(solHave!=null?' ('+solStr(solHave)+' SOL)':'')],['Arrives in',confirmWhen()]],
     notes:[...(bf.setupIncluded?[`Includes the one-time setup of ${r.symbol} on the bridge (${solStr(feeSchedule()?.setupLamports||0)} SOL). Later deposits of ${r.symbol} pay only the bridge fee.`]:[]),...(feeL>0n?['The bridge fee pays for the Monero transaction that credits your tokens: it goes to the XMR20 fee wallet, which funds the bridge’s Monero fees.'+(bf.setupIncluded?' The setup part goes to the bridge operator’s Solana wallet.':'')]:[])],button:'Approve and bridge'});same(e);
