   await journal.write(j=>{journal.account(j,w.tokenAddress).claims[l.claim]={phase:'prepared',symbol:r.symbol,asset:r.asset,body:prep.body,created:Date.now()};});testHook('claim-prepared');
   setProgress(prep.signWith==='address-spend-key'?'Signing the claim with this account’s Monero spend key locally (nothing is spent; no key image)…':'Deriving the legacy output key from your Monero keys and signing locally…');const a=account();const sig=prep.signWith==='address-spend-key'?await oneShot('private-claim.worker.js','sign-address-claim',{seed:a.xmrSeed,owner:a.xmr,review:{messageHash:prep.messageHash,legacyOwner:prep.legacyOwner}}):await oneShot('private-claim.worker.js','sign-claim',{seed:a.xmrSeed,owner:a.xmr,review:{messageHash:prep.messageHash,P:prep.P,txPublicKey:prep.txPublicKey,outputIndex:prep.outputIndex}});same(e);
   await journal.write(j=>{journal.account(j,w.tokenAddress).claims[l.claim]={phase:'signed',symbol:r.symbol,asset:r.asset,body:prep.body,signature:sig.signature,created:Date.now()};});testHook('claim-signed');
